using System;
using System.Reflection;
using EmberBastion;
namespace EmberBastion { public static class Bench { public static bool NoCards; } }
class ReinforcementBalanceProbe {
 static string Run(uint seed,int field,int card1,int card2,bool noCards,int policy){Bench.NoCards=noCards;var b=new Battle(seed,field);b.EnableReinforcements();int tick=0,picked=0;var offered=typeof(ReinforcementDraft).GetField("offered",BindingFlags.Instance|BindingFlags.NonPublic);while(b.Phase!=Phase.Won&&b.Phase!=Phase.Lost&&tick<120000){if(b.ReinforcementPending){int c=picked++==0?card1:card2;offered.SetValue(b.Reinforcements,new[]{c,(c+1)%7,(c+2)%7});if(!b.ChooseReinforcement(c))throw new Exception("card choice failed");}if(tick%60==0){for(int slot=0;slot<b.Field.Slots.Length;slot++)if(b.At(slot)==null){int kind=policy==0?Smart.Kind(field,slot):policy==1?0:policy==2?1:policy==3?2:new[]{0,0,1,2}[slot%4];if(b.Gold>=Balance.Troops[kind].Cost)b.Place(kind,slot);}foreach(var u in b.Units){if(u.Level==1&&b.Gold>=50)b.Upgrade(u.Slot);else if(u.Kind==0&&(policy==0||policy==1)&&u.Level==2&&b.Gold>=90)b.UpgradeBranch(u.Slot,2);}}if(b.Phase==Phase.Preparation&&!b.Start())throw new Exception("start failed");if(b.EmberCD<=0&&b.Enemies.Count>=3)b.Ember(b.Enemies[b.Enemies.Count/2].Position);b.Step(1.0/60);tick++;}return (b.Phase==Phase.Won?"Won":b.Phase==Phase.Lost?"Lost":"Stalled")+","+b.PeakAlive+","+picked;}
 static int Main(){try{Console.WriteLine("seed,field,policy,card1,card2,outcome,peak,picked");foreach(uint seed in new uint[]{29,41,57,73})for(int field=0;field<3;field++)for(int policy=0;policy<5;policy++){Console.WriteLine(seed+","+field+","+policy+",none,none,"+Run(seed,field,0,1,true,policy));for(int a=0;a<7;a++)for(int c=a+1;c<7;c++)Console.WriteLine(seed+","+field+","+policy+","+a+","+c+","+Run(seed,field,a,c,false,policy));}return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
static class Smart {
 static readonly System.Collections.Generic.Dictionary<int,int[]> cache=new System.Collections.Generic.Dictionary<int,int[]>();
 static Point P(int f,double d){return f==0?Balance.Path(d):Balance.Fields[f].Path(d);}
 static double Cover(int f,Point s,double range,double min){double per=f==0?Balance.Perimeter:Balance.Fields[f].Perimeter;int n=0,inside=0;for(double d=0;d<per;d+=16){n++;double dist=Point.Distance(P(f,d),s);if(dist<=range&&dist>=min)inside++;}return (double)inside/n;}
 // Swords on the half of slots that touch the most road within melee range; the rest alternate archer/bomb by long-range coverage.
 public static int Kind(int f,int slot){int[] a;if(!cache.TryGetValue(f,out a)){var S=Balance.Fields[f].Slots;int m=S.Length;var idx=new System.Collections.Generic.List<int>();for(int i=0;i<m;i++)idx.Add(i);idx.Sort((x,y)=>{int comparison=Cover(f,S[y],120,0).CompareTo(Cover(f,S[x],120,0));return comparison!=0?comparison:x.CompareTo(y);});a=new int[m];var rest=new System.Collections.Generic.List<int>();for(int i=0;i<m;i++){if(i<m/2)a[idx[i]]=0;else rest.Add(idx[i]);}rest.Sort((x,y)=>{int comparison=Cover(f,S[y],210,60).CompareTo(Cover(f,S[x],210,60));return comparison!=0?comparison:x.CompareTo(y);});for(int i=0;i<rest.Count;i++)a[rest[i]]=i%2==0?1:2;cache[f]=a;}return a[slot];}
}
